require_once __DIR__ . '/includes/auth.php'; requireLogin(); $userId=(int)$_SESSION['user_id']; $pageTitle='Statements'; $type=(string)($_GET['type']??''); if(!in_array($type,['deposit','withdrawal','commission','reward','investment'],true))$type=null; $transactions=getUserTransactions($userId,$type,100);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> - <?= e(APP_NAME) ?></title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/includes/header.php'; ?><?php include __DIR__.'/includes/sidebar.php'; ?><main class="main-content"><div class="page-title"><span class="eyebrow">ACCOUNT LEDGER</span><h1>Statements</h1><p class="muted">A complete record of demo account activity.</p></div><section class="panel"><div class="tabs"><a class="<?= !$type?'active':'' ?>" href="statements.php">All</a><?php foreach(['deposit','withdrawal','commission','reward','investment'] as $filter): ?><a class="<?= $type===$filter?'active':'' ?>" href="statements.php?type=<?= e($filter) ?>"><?= e(ucfirst($filter)) ?></a><?php endforeach; ?></div><?php if(!$transactions): ?><p class="empty">No transactions found.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Type</th><th>Description</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($transactions as $tx): ?><tr><td><?= e(ucfirst($tx['type'])) ?></td><td><?= e($tx['description']) ?></td><td><?= formatCurrency($tx['amount']) ?></td><td><span class="badge <?= e($tx['status']) ?>"><?= e(ucfirst($tx['status'])) ?></span></td><td><?= e(formatDate($tx['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></main><?php include __DIR__.'/includes/bottom-nav.php'; ?><?php include __DIR__.'/includes/footer.php'; ?><script src="assets/js/app.js"></script></body></html>
